head.script:
// 테스트 설명, 유효성 값 설정
// 이 샘플(_2) 은 비교 조건(searchTarget, caseSensitive) 축을 담당한다. 적용 전제와 설정값(true/false/미설정), 검색 건수 축은 _1 샘플에서 다룬다.
scwin.tData = {
    "description" : "[autoComplete > P > autoFocus]<br/>입력값이 아이템과 정확하게 일치하면 포커스를 nextTabID 속성의 컴포넌트로 이동시킵니다.",
    "validation" : [
        "사용자의 입력값과 비교하는 아이템 값은 searchTarget 속성값에 따라 달라집니다.",
        "caseSensitive='false' 이면 영문 대소문자를 구분하지 않고 비교합니다.",
    ]
}

// 아이템 (Label 과 Value 가 서로 다르고 영문 대소문자가 섞여 있다)
scwin.arrCity = [
    { "label" : "Seoul", "value" : "SEL" },
    { "label" : "Seongnam", "value" : "SNM" },
    { "label" : "Busan", "value" : "PUS" },
    { "label" : "Busanjin", "value" : "BSJ" },
    { "label" : "Jeju", "value" : "CJU" }
];



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 아이템 DataList 생성
    scwin.createCityDataList("dlt_city");
    dlt_city.setJSON(scwin.arrCity);

    // 포커스 확인 버튼 클릭 시 포커스가 버튼으로 옮겨가고 목록이 닫히므로 mousedown capture 단계에서 상태를 기록
    btn_getFocusInfo.render.addEventListener("mousedown", scwin.captureFocusState, true);

    // comp 초기 생성
    scwin.comp_init();
};



scwin.createCityDataList = function (dltID) {
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' baseNode="list" repeatNode="map" id="' + dltID + '">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="label" name="label" dataType="text"></w2:column>';
    strDlt += '<w2:column id="value" name="value" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제 (remove 로는 지워지지 않는 이전 nextTabID 연결 정보도 함께 정리)
    if (typeof target1 !== 'undefined') {
        delete WebSquare.tabOrder[target1.id];
        target1.remove();
    }

    if (typeof input2 !== 'undefined') {
        delete WebSquare.tabOrder[input2.id];
        input2.remove();
    }

    $c.gcm.createLabel('label="[전제]\n- autoFocus=true, nextTabID=input2 고정 (위쪽 입력창이 input2, 아래쪽이 대상 AutoComplete)\n- 아이템(Label / Value) : Seoul / SEL, Seongnam / SNM, Busan / PUS, Busanjin / BSJ, Jeju / CJU\n[절차] 결과창 clear -> 대상 클릭 -> Seoul, SEL, seoul, sel 중 하나 입력 -> 포커스 확인"', '', 'label1');

    scwin.typedValue = "";

    let properties = {
        autoFocus : "true",
        nextTabID : "input2",
        searchTarget : con_searchTarget.getValue(),
        caseSensitive : con_caseSensitive.getText(),
    }

    let cList = $c.gcm.createCList(properties);

    let strTarget = '';
    strTarget += '<w2:autoComplete ' + $c.gcm.getNameSpace() + ' ' + cList + ' style="width:200px; height:30px;">';
    strTarget += '<w2:choices>';
    strTarget += '<w2:itemset nodeset="data:dlt_city">';
    strTarget += '<w2:label ref="label"></w2:label>';
    strTarget += '<w2:value ref="value"></w2:value>';
    strTarget += '</w2:itemset>';
    strTarget += '</w2:choices>';
    strTarget += '</w2:autoComplete>';

    // nextTabID 대상(input2)을 target1 보다 먼저 생성
    await $c.gcm.createEmptyInput('style="width:200px; height:30px;"', '', 'input2');
    await $p.dynamicCreate("target1", "autoComplete", strTarget, $c.gcm.getTestGroup());

    // 포커스 이동 후에는 입력창의 표시값이 바뀔 수 있어 사용자가 입력한 값을 따로 기록
    document.querySelector("input[id='" + target1.id + "_input']").addEventListener("input", function (e) {
        scwin.typedValue = e.target.value;
    });
}



// 버튼 mousedown 시점(포커스가 버튼으로 옮겨가기 전)의 포커스 위치와 리스트창 표시 아이템 기록
scwin.captureFocusState = function (e) {
    let activeElem = document.activeElement;
    if (target1.render.contains(activeElem)) {
        scwin.focusState = "target1";
    } else if (input2.render.contains(activeElem)) {
        scwin.focusState = "input2";
    } else {
        scwin.focusState = activeElem.id || activeElem.tagName;
    }

    scwin.listState = null;
    let itemTableElem = document.querySelector("[id='" + target1.id + "_itemTable']");
    if (!itemTableElem || getComputedStyle(itemTableElem).display === "none" || getComputedStyle(itemTableElem).visibility === "hidden") {
        return;
    }
    let rowElems = itemTableElem.querySelectorAll("[id='" + target1.id + "_itemTable_main'] tr, li");
    scwin.listState = Array.prototype.filter.call(rowElems, function (row) {
        return row.offsetParent !== null;
    }).map(function (row) {
        return row.textContent;
    });
};



// 입력값, 검색된 아이템(리스트창이 열려 있는 경우), 포커스 위치 출력 (validation 1, 2)
scwin.btn_getFocusInfo_onclick = function (e) {
    let strResult = "입력값 : " + scwin.typedValue;
    if (scwin.listState) {
        strResult += " -> 검색된 아이템 : " + scwin.listState.join(" / ");
    }
    wf_body_bottom.getObj("scwin").setReturnValue(strResult + " -> 포커스 : " + scwin.focusState);
};
